import { getTool } from './tools'

export type SeoFaq = { question: string; answer: string }
export type SeoLink = { slug: string; label: string; description: string }
export interface ToolSeoContent {
  seoTitle: string; metaDescription: string; intro: string; overview: string[]; useCases: string[]
  howItWorks: string[]; supportedFormats: string; features: string[]; qualityOrOutputNotes: string
  limitations: string; privacy: string; tips: string[]; troubleshooting: SeoFaq[]
  relatedTools: SeoLink[]; faq: SeoFaq[]
}

const localPrivacy = 'Your selected files are read and processed in this browser tab. Document bytes are not uploaded to PDFHope, although the site code itself is delivered over the network.'
const serverPrivacy = 'This conversion uses a secure server workflow. The file is encrypted in transit, streamed to the conversion provider in zero-storage mode, processed in memory, and not permanently stored by PDFHope or the provider.'
const q = (question: string, answer: string): SeoFaq => ({ question, answer })
const r = (slug: string, label: string, description: string): SeoLink => ({ slug, label, description })

type Draft = Omit<ToolSeoContent, 'seoTitle'|'metaDescription'|'howItWorks'|'limitations'|'privacy'> & Partial<Pick<ToolSeoContent, 'seoTitle'|'metaDescription'|'howItWorks'|'limitations'|'privacy'>>
const make = (slug: string, draft: Draft): ToolSeoContent => {
  const tool = getTool(slug)!
  return { seoTitle: `${tool.name} Online | PDFHope`, metaDescription: tool.description, howItWorks: tool.instructions, limitations: tool.limitations, privacy: localPrivacy, ...draft }
}

